SELECT
,
fc.name as first_category_name,
sc.name as second_category_name,
tc.name as third_category_name
FROM report_main rm
LEFT JOIN report_category fc ON rm.first_category_id = fc.id
LEFT JOIN report_category sc ON rm.second_category_id = sc.id
LEFT JOIN report_category tc ON rm.third_category_id = tc.id

    AND rm.status = #{query.status}
    AND rm.reported_type = #{query.reportedType}
    AND rm.user_id = #{query.userId}
    AND rm.id = #{query.reportId}
    AND rm.created_time >= #{query.startTime}
    AND rm.created_time <= #{query.endTime}
    AND rm.first_category_id = #{query.firstCategoryId}
    AND rm.second_category_id = #{query.secondCategoryId}
    AND rm.third_category_id = #{query.thirdCategoryId}
    AND rm.risk_level = #{query.riskLevel}

ORDER BY rm.created_time DESC

SELECT , fc.name as first_category_name, sc.name as second_category_name, tc.name as third_category_name FROM report_main rm LEFT JOIN report_category fc ON rm.first_category_id = fc.id LEFT JOIN report_category sc ON rm.second_category_id = sc.id LEFT JOIN report_category tc ON rm.third_category_id = tc.id
AND rm.user_id = #{userId} AND rm.status = #{status}
ORDER BY rm.created_time DESC
